"""Matriz de lectura de fuentes primarias; no certifica novedad científica."""
from pathlib import Path
import json,csv
ROOT=Path(__file__).resolve().parents[2]
ITEMS=[
('helf1997','GAM en odontología','1997','https://pubmed.ncbi.nlm.nih.gov/9458579/','Título y resumen completos consultados','Estudia relaciones no lineales con caries en dientes primarios.','Mismo fenómeno, pero no acredita identidad con nuestra etiqueta binaria ni población. Impide presentar GAM en caries como una idea inédita.','BCE + ranking por pares e interacciones seleccionadas no se describen en el resumen; su ausencia en el resumen no demuestra ausencia en toda la literatura.'),
('lou2012','GAM para clasificación y regresión','2012','https://www.cs.cornell.edu/~yinlou/papers/lou-kdd12.pdf','Resumen, introducción y formulación consultados','Suma funciones univariadas interpretables; compara splines y árboles.','La representación aditiva y los splines son antecedentes establecidos.','Nuestro objetivo incluye ranking, L2 y una heurística de interacción; no se acredita una regla de aprendizaje nueva solo por combinarlos.'),
('lou2013','GA²M e interacciones por pares','2013','https://www.microsoft.com/en-us/research/wp-content/uploads/2017/06/kdd13.pdf','Resumen, introducción y ecuaciones consultados','Añade interacciones seleccionadas a modelos aditivos y usa FAST para candidatos.','Términos univariados más pocas interacciones no son una arquitectura nueva.','Nuestro selector usa asociación con residuos y submuestras, no FAST; la diferencia implementada no equivale a superioridad metodológica.'),
('gao2015','Consistencia de optimización AUC por pares','2015','https://arxiv.org/abs/1208.0645','Título y resumen consultados','Analiza pérdidas sustitutas por pares; incluye la pérdida logística.','El ranking logístico positivo-negativo ya tiene antecedentes.','No se traslada su garantía asintótica automáticamente a la mezcla, representación seleccionada y muestreo finito de nuestro algoritmo.'),
('agarwal2014','Cotas de ranking con pérdidas propias','2014','https://jmlr.org/papers/v15/agarwal14b.html','Título y resumen consultados','Relaciona pérdidas propias de clasificación y ranking bipartito.','Una pérdida logística puede inducir ordenamiento; añadir ranking no asegura una mejora.','No se demuestra aquí una cota de generalización equivalente para el modelo propuesto.'),
('nori2019','InterpretML y Explainable Boosting Machine','2019','https://arxiv.org/abs/1909.09223','Título y resumen; documentación oficial de EBM consultados','Ofrece modelos interpretables, incluidos EBMs aditivos.','Referencia directa para capacidad predictiva e interpretación aditiva.','Nuestro núcleo usa splines y optimización de coeficientes; EBM usa boosting. Se añade comparación empírica acotada, no una declaración de dominio del estado del arte.'),
('greenwell2023','EBM con sparsity mediante LASSO','2023','https://arxiv.org/abs/2311.07452','Título y resumen consultados','Repondera y elimina términos del EBM mediante LASSO.','Regularizar o reducir términos para interpretabilidad tampoco es una idea inédita.','Nuestro L2 no induce la misma selección dispersa y no replica el procedimiento propuesto en ese trabajo.'),
('ravikumar2007','Sparse Additive Models (SpAM)','2007','https://proceedings.neurips.cc/paper/2007/hash/42e7aaa88b48137a16a1acd04ed91125-Abstract.html','Título y resumen consultados','Combina modelado aditivo no paramétrico y sparsity en regresión/clasificación.','Modelo aditivo regularizado es una familia con historia teórica previa.','No se ha probado aquí la misma propiedad de sparsity ni sus cotas; nuestra propiedad probada es convexidad condicional.')]
def main():
 out=ROOT/'_static/entregable3';out.mkdir(parents=True,exist_ok=True)
 cols=['clave','familia_afin','anio','fuente_primaria','lectura_efectuada','mecanismo_cercano','que_se_conserva','diferencia_y_limite']
 with (out/'matriz_novedad.csv').open('w') as f:
  w=csv.writer(f);w.writerow(cols);w.writerows(ITEMS)
 raw=json.loads((ROOT/'proyecto_final_caries/revision_literatura/resultados/registro_consultas.json').read_text());rows=[]
 for x in raw:rows.append(dict(base=x['base'],consulta=x['id_consulta'],cadena=x['cadena'],fecha_utc=x['fecha_utc'],estado=x['estado'],recuperados=len(x.get('resultados',x.get('identificadores',[]))),total_indice=x.get('total_indice_no_pertinencia'),revisados_manualmente='No contabilizados automáticamente',relevantes='Requiere cribado; la recuperación no implica pertinencia',url=x['url']))
 with (out/'matriz_busquedas.csv').open('w') as f:
  w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
 (out/'veredicto_novedad.json').write_text(json.dumps(dict(bases_consultadas=['PubMed','Crossref (registro bibliográfico; no equivalente a Scopus)','arXiv'],cadenas_distintas=5,intentos=15,respuestas_satisfactorias=sum(x['estado']=='Consulta respondida' for x in raw),lecturas_cercanas=8,veredicto='R1 no acreditado. No se afirma que nadie haya usado el mecanismo exacto ni que la propuesta sea científicamente original.',alcance='Búsqueda estructurada preliminar, metadatos y lectura focalizada. No revisión sistemática exhaustiva.',limites=['Un intento de Crossref falló y queda registrado.','Consultas arXiv con frases estrictas no recuperaron entradas; cero resultados no prueba novedad.','Las consultas de PubMed y Crossref pueden devolver resultados poco pertinentes; sus conteos no se convierten en número de artículos relevantes.','Se encontró antecedente de GAM aplicado a caries, además de arquitecturas aditivas con interacciones y ranking logístico en otras tareas.']),indent=2,ensure_ascii=False))
 print('Ocho métodos afines y registro de 15 intentos conservados; R1 no acreditado.')
if __name__=='__main__':main()
